/**
 * 数据同步服务
 * 负责应用间的数据共享和同步
 */

import storage from '@system.storage'

// 数据键名定义
export const DATA_KEYS = {
  // 姿态识别数据
  POSTURE_LATEST: 'posture_latest',
  POSTURE_HISTORY: 'posture_history',
  POSTURE_SCORE: 'posture_score',
  POSTURE_ALERTS: 'posture_alerts',

  // 健康数据
  HEALTH_HEART_RATE: 'health_heart_rate',
  HEALTH_STEPS: 'health_steps',
  HEALTH_SLEEP: 'health_sleep',

  // 通用数据
  USER_SETTINGS: 'user_settings',
  DAILY_GOALS: 'daily_goals'
}

class DataSyncService {
  constructor() {
    this.listeners = new Map()
  }

  /**
   * 保存数据
   * @param {string} key - 数据键名
   * @param {*} value - 数据值
   * @returns {Promise}
   */
  async setData(key, value) {
    return new Promise((resolve, reject) => {
      storage.set({
        key,
        value: JSON.stringify(value),
        success: () => {
          this.notifyListeners(key, value)
          resolve()
        },
        fail: (data, code) => {
          console.error(`[DataSync] 设置数据失败: ${key}`, code)
          reject(new Error(`设置数据失败: ${code}`))
        }
      })
    })
  }

  /**
   * 获取数据
   * @param {string} key - 数据键名
   * @param {*} defaultValue - 默认值
   * @returns {Promise<*>}
   */
  async getData(key, defaultValue = null) {
    return new Promise((resolve, reject) => {
      storage.get({
        key,
        success: (data) => {
          try {
            resolve(data ? JSON.parse(data) : defaultValue)
          } catch (e) {
            resolve(defaultValue)
          }
        },
        fail: (data, code) => {
          console.error(`[DataSync] 获取数据失败: ${key}`, code)
          resolve(defaultValue)
        }
      })
    })
  }

  /**
   * 删除数据
   * @param {string} key - 数据键名
   * @returns {Promise}
   */
  async removeData(key) {
    return new Promise((resolve, reject) => {
      storage.delete({
        key,
        success: () => {
          this.notifyListeners(key, null)
          resolve()
        },
        fail: (data, code) => {
          console.error(`[DataSync] 删除数据失败: ${key}`, code)
          reject(new Error(`删除数据失败: ${code}`))
        }
      })
    })
  }

  /**
   * 订阅数据变化
   * @param {string} key - 数据键名
   * @param {Function} callback - 回调函数
   */
  subscribe(key, callback) {
    if (!this.listeners.has(key)) {
      this.listeners.set(key, [])
    }
    this.listeners.get(key).push(callback)
  }

  /**
   * 取消订阅
   * @param {string} key - 数据键名
   * @param {Function} callback - 回调函数
   */
  unsubscribe(key, callback) {
    if (this.listeners.has(key)) {
      const callbacks = this.listeners.get(key)
      const index = callbacks.indexOf(callback)
      if (index > -1) {
        callbacks.splice(index, 1)
      }
    }
  }

  /**
   * 通知监听者
   * @param {string} key - 数据键名
   * @param {*} value - 数据值
   */
  notifyListeners(key, value) {
    if (this.listeners.has(key)) {
      this.listeners.get(key).forEach(callback => {
        try {
          callback(value)
        } catch (e) {
          console.error(`[DataSync] 通知监听者失败: ${key}`, e)
        }
      })
    }
  }

  /**
   * 保存姿态数据
   * @param {Object} postureData - 姿态数据
   */
  async savePostureData(postureData) {
    const data = {
      ...postureData,
      timestamp: Date.now()
    }
    await this.setData(DATA_KEYS.POSTURE_LATEST, data)

    // 添加到历史记录
    const history = await this.getData(DATA_KEYS.POSTURE_HISTORY, [])
    history.unshift(data)
    // 保留最近100条记录
    if (history.length > 100) {
      history.pop()
    }
    await this.setData(DATA_KEYS.POSTURE_HISTORY, history)
  }

  /**
   * 保存健康数据
   * @param {string} type - 数据类型 (heart_rate/steps/sleep)
   * @param {*} data - 健康数据
   */
  async saveHealthData(type, data) {
    const key = `health_${type}`
    await this.setData(key, {
      ...data,
      timestamp: Date.now()
    })
  }
}

export default new DataSyncService()

/**
 * 事件总线服务
 * 用于应用内和应用间的事件通信
 */

class EventBus {
  constructor() {
    this.subscribers = new Map()
  }

  /**
   * 订阅事件
   * @param {string} event - 事件名称
   * @param {Function} callback - 回调函数
   * @returns {Function} 取消订阅函数
   */
  subscribe(event, callback) {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, [])
    }
    this.subscribers.get(event).push(callback)

    // 返回取消订阅函数
    return () => {
      this.unsubscribe(event, callback)
    }
  }

  /**
   * 取消订阅
   * @param {string} event - 事件名称
   * @param {Function} callback - 回调函数
   */
  unsubscribe(event, callback) {
    if (this.subscribers.has(event)) {
      const callbacks = this.subscribers.get(event)
      const index = callbacks.indexOf(callback)
      if (index > -1) {
        callbacks.splice(index, 1)
      }
    }
  }

  /**
   * 发布事件
   * @param {string} event - 事件名称
   * @param {*} data - 事件数据
   */
  publish(event, data) {
    if (this.subscribers.has(event)) {
      this.subscribers.get(event).forEach(callback => {
        try {
          callback(data)
        } catch (e) {
          console.error(`[EventBus] 事件处理错误: ${event}`, e)
        }
      })
    }
  }

  /**
   * 清除所有订阅
   */
  clear() {
    this.subscribers.clear()
  }
}

// 预定义的事件类型
export const EVENTS = {
  // 姿态识别事件
  POSTURE_UPDATE: 'posture:update',
  POSTURE_ALERT: 'posture:alert',
  POSTURE_SCORE_UPDATE: 'posture:score:update',

  // 健康数据事件
  HEALTH_HEART_RATE_UPDATE: 'health:heart_rate:update',
  HEALTH_STEPS_UPDATE: 'health:steps:update',
  HEALTH_SLEEP_UPDATE: 'health:sleep:update',

  // 系统事件
  APP_CONNECTED: 'app:connected',
  APP_DISCONNECTED: 'app:disconnected',
  SENSOR_DATA: 'sensor:data'
}

export default new EventBus()

/**
 * 存储服务
 * 封装 OpenVela 存储 API，提供统一的存储接口
 */

import storage from '@system.storage'

class StorageService {
  /**
   * 保存字符串数据
   * @param {string} key - 键名
   * @param {string} value - 值
   * @returns {Promise}
   */
  setString(key, value) {
    return new Promise((resolve, reject) => {
      storage.set({
        key,
        value,
        success: () => resolve(),
        fail: (data, code) => {
          console.error(`[Storage] 保存失败: ${key}`, code)
          reject(new Error(`保存失败: ${code}`))
        }
      })
    })
  }

  /**
   * 获取字符串数据
   * @param {string} key - 键名
   * @param {string} defaultValue - 默认值
   * @returns {Promise<string>}
   */
  getString(key, defaultValue = '') {
    return new Promise((resolve) => {
      storage.get({
        key,
        success: (data) => resolve(data || defaultValue),
        fail: () => resolve(defaultValue)
      })
    })
  }

  /**
   * 保存对象数据（自动 JSON 序列化）
   * @param {string} key - 键名
   * @param {Object} value - 对象值
   * @returns {Promise}
   */
  setObject(key, value) {
    return this.setString(key, JSON.stringify(value))
  }

  /**
   * 获取对象数据（自动 JSON 反序列化）
   * @param {string} key - 键名
   * @param {Object} defaultValue - 默认值
   * @returns {Promise<Object>}
   */
  async getObject(key, defaultValue = {}) {
    const data = await this.getString(key)
    try {
      return data ? JSON.parse(data) : defaultValue
    } catch (e) {
      return defaultValue
    }
  }

  /**
   * 保存数字数据
   * @param {string} key - 键名
   * @param {number} value - 数值
   * @returns {Promise}
   */
  setNumber(key, value) {
    return this.setString(key, String(value))
  }

  /**
   * 获取数字数据
   * @param {string} key - 键名
   * @param {number} defaultValue - 默认值
   * @returns {Promise<number>}
   */
  async getNumber(key, defaultValue = 0) {
    const data = await this.getString(key)
    const num = Number(data)
    return isNaN(num) ? defaultValue : num
  }

  /**
   * 保存布尔数据
   * @param {string} key - 键名
   * @param {boolean} value - 布尔值
   * @returns {Promise}
   */
  setBoolean(key, value) {
    return this.setString(key, String(value))
  }

  /**
   * 获取布尔数据
   * @param {string} key - 键名
   * @param {boolean} defaultValue - 默认值
   * @returns {Promise<boolean>}
   */
  async getBoolean(key, defaultValue = false) {
    const data = await this.getString(key)
    return data === 'true' ? true : data === 'false' ? false : defaultValue
  }

  /**
   * 删除数据
   * @param {string} key - 键名
   * @returns {Promise}
   */
  remove(key) {
    return new Promise((resolve, reject) => {
      storage.delete({
        key,
        success: () => resolve(),
        fail: (data, code) => {
          console.error(`[Storage] 删除失败: ${key}`, code)
          reject(new Error(`删除失败: ${code}`))
        }
      })
    })
  }

  /**
   * 清除所有数据
   * @returns {Promise}
   */
  clear() {
    return new Promise((resolve, reject) => {
      storage.clear({
        success: () => resolve(),
        fail: (data, code) => {
          console.error(`[Storage] 清除失败`, code)
          reject(new Error(`清除失败: ${code}`))
        }
      })
    })
  }

  /**
   * 获取所有键名
   * @returns {Promise<string[]>}
   */
  keys() {
    return new Promise((resolve, reject) => {
      storage.keys({
        success: (data) => resolve(data),
        fail: (data, code) => {
          console.error(`[Storage] 获取键名失败`, code)
          reject(new Error(`获取键名失败: ${code}`))
        }
      })
    })
  }
}

export default new StorageService()

/**
 * 传感器服务
 * 封装 OpenVela 传感器 API，提供统一的传感器数据采集接口
 */

import sensor from '@system.sensor'

class SensorService {
  constructor() {
    this.isAccelerometerActive = false
    this.isGyroscopeActive = false
    this.accelerometerCallback = null
    this.gyroscopeCallback = null
  }

  /**
   * 订阅加速度传感器
   * @param {Function} callback - 回调函数，接收 {x, y, z} 数据
   * @param {Object} options - 配置选项
   */
  subscribeAccelerometer(callback, options = {}) {
    if (this.isAccelerometerActive) {
      console.warn('[Sensor] 加速度传感器已激活')
      return
    }

    this.accelerometerCallback = callback

    sensor.subscribeAccelerometer({
      callback: (data) => {
        if (this.accelerometerCallback) {
          this.accelerometerCallback({
            x: data.x,
            y: data.y,
            z: data.z,
            timestamp: Date.now()
          })
        }
      },
      fail: (data, code) => {
        console.error('[Sensor] 加速度传感器订阅失败', code)
      }
    })

    this.isAccelerometerActive = true
    console.log('[Sensor] 加速度传感器已订阅')
  }

  /**
   * 取消订阅加速度传感器
   */
  unsubscribeAccelerometer() {
    if (this.isAccelerometerActive) {
      sensor.unsubscribeAccelerometer({
        success: () => {
          this.isAccelerometerActive = false
          this.accelerometerCallback = null
          console.log('[Sensor] 加速度传感器已取消订阅')
        },
        fail: (data, code) => {
          console.error('[Sensor] 加速度传感器取消订阅失败', code)
        }
      })
    }
  }

  /**
   * 订阅陀螺仪
   * @param {Function} callback - 回调函数，接收 {x, y, z} 数据
   * @param {Object} options - 配置选项
   */
  subscribeGyroscope(callback, options = {}) {
    if (this.isGyroscopeActive) {
      console.warn('[Sensor] 陀螺仪已激活')
      return
    }

    this.gyroscopeCallback = callback

    sensor.subscribeGyroscope({
      callback: (data) => {
        if (this.gyroscopeCallback) {
          this.gyroscopeCallback({
            x: data.x,
            y: data.y,
            z: data.z,
            timestamp: Date.now()
          })
        }
      },
      fail: (data, code) => {
        console.error('[Sensor] 陀螺仪订阅失败', code)
      }
    })

    this.isGyroscopeActive = true
    console.log('[Sensor] 陀螺仪已订阅')
  }

  /**
   * 取消订阅陀螺仪
   */
  unsubscribeGyroscope() {
    if (this.isGyroscopeActive) {
      sensor.unsubscribeGyroscope({
        success: () => {
          this.isGyroscopeActive = false
          this.gyroscopeCallback = null
          console.log('[Sensor] 陀螺仪已取消订阅')
        },
        fail: (data, code) => {
          console.error('[Sensor] 陀螺仪取消订阅失败', code)
        }
      })
    }
  }

  /**
   * 订阅心率传感器
   * @param {Function} callback - 回调函数
   */
  subscribeHeartRate(callback) {
    sensor.subscribeHeartRate({
      callback: (data) => {
        callback({
          value: data.value,
          timestamp: Date.now()
        })
      },
      fail: (data, code) => {
        console.error('[Sensor] 心率传感器订阅失败', code)
      }
    })
  }

  /**
   * 取消订阅心率传感器
   */
  unsubscribeHeartRate() {
    sensor.unsubscribeHeartRate({
      success: () => {
        console.log('[Sensor] 心率传感器已取消订阅')
      },
      fail: (data, code) => {
        console.error('[Sensor] 心率传感器取消订阅失败', code)
      }
    })
  }

  /**
   * 取消所有传感器订阅
   */
  unsubscribeAll() {
    this.unsubscribeAccelerometer()
    this.unsubscribeGyroscope()
    this.unsubscribeHeartRate()
  }

  /**
   * 获取传感器状态
   * @returns {Object} 传感器状态
   */
  getStatus() {
    return {
      accelerometer: this.isAccelerometerActive,
      gyroscope: this.isGyroscopeActive
    }
  }
}

export default new SensorService()

/**
 * 日期工具函数
 */

/**
 * 格式化日期
 * @param {Date|number|string} date - 日期对象或时间戳
 * @param {string} format - 格式化模式
 * @returns {string}
 */
export function formatDate(date, format = 'YYYY-MM-DD') {
  const d = new Date(date)
  const year = d.getFullYear()
  const month = String(d.getMonth() + 1).padStart(2, '0')
  const day = String(d.getDate()).padStart(2, '0')
  const hours = String(d.getHours()).padStart(2, '0')
  const minutes = String(d.getMinutes()).padStart(2, '0')
  const seconds = String(d.getSeconds()).padStart(2, '0')

  return format
    .replace('YYYY', year)
    .replace('MM', month)
    .replace('DD', day)
    .replace('HH', hours)
    .replace('mm', minutes)
    .replace('ss', seconds)
}

/**
 * 获取今天的日期字符串
 * @param {string} format - 格式化模式
 * @returns {string}
 */
export function getToday(format = 'YYYY-MM-DD') {
  return formatDate(new Date(), format)
}

/**
 * 获取当前时间字符串
 * @returns {string}
 */
export function getCurrentTime() {
  return formatDate(new Date(), 'HH:mm:ss')
}

/**
 * 计算两个日期之间的天数差
 * @param {Date} date1 - 日期1
 * @param {Date} date2 - 日期2
 * @returns {number}
 */
export function daysBetween(date1, date2) {
  const d1 = new Date(date1)
  const d2 = new Date(date2)
  const diffTime = Math.abs(d2 - d1)
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24))
}

/**
 * 获取日期的开始时间（00:00:00）
 * @param {Date} date - 日期
 * @returns {Date}
 */
export function getStartOfDay(date = new Date()) {
  const d = new Date(date)
  d.setHours(0, 0, 0, 0)
  return d
}

/**
 * 获取日期的结束时间（23:59:59）
 * @param {Date} date - 日期
 * @returns {Date}
 */
export function getEndOfDay(date = new Date()) {
  const d = new Date(date)
  d.setHours(23, 59, 59, 999)
  return d
}

/**
 * 判断是否是同一天
 * @param {Date} date1 - 日期1
 * @param {Date} date2 - 日期2
 * @returns {boolean}
 */
export function isSameDay(date1, date2) {
  const d1 = new Date(date1)
  const d2 = new Date(date2)
  return (
    d1.getFullYear() === d2.getFullYear() &&
    d1.getMonth() === d2.getMonth() &&
    d1.getDate() === d2.getDate()
  )
}

/**
 * 获取星期几（中文）
 * @param {Date} date - 日期
 * @returns {string}
 */
export function getWeekdayName(date) {
  const days = ['日', '一', '二', '三', '四', '五', '六']
  return '星期' + days[new Date(date).getDay()]
}

/**
 * 获取月份名称（中文）
 * @param {number} month - 月份（0-11）
 * @returns {string}
 */
export function getMonthName(month) {
  const months = [
    '一月', '二月', '三月', '四月', '五月', '六月',
    '七月', '八月', '九月', '十月', '十一月', '十二月'
  ]
  return months[month]
}

/**
 * 获取相对时间描述
 * @param {Date} date - 日期
 * @returns {string}
 */
export function getRelativeTime(date) {
  const now = new Date()
  const d = new Date(date)
  const diff = now - d

  const minutes = Math.floor(diff / 60000)
  const hours = Math.floor(diff / 3600000)
  const days = Math.floor(diff / 86400000)

  if (minutes < 1) return '刚刚'
  if (minutes < 60) return `${minutes}分钟前`
  if (hours < 24) return `${hours}小时前`
  if (days < 7) return `${days}天前`
  if (days < 30) return `${Math.floor(days / 7)}周前`
  return formatDate(date, 'MM-DD')
}

/**
 * 格式化工具函数
 */

/**
 * 格式化数字（添加千位分隔符）
 * @param {number} num - 数字
 * @returns {string}
 */
export function formatNumber(num) {
  return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',')
}

/**
 * 格式化距离
 * @param {number} meters - 米
 * @returns {string}
 */
export function formatDistance(meters) {
  if (meters < 1000) {
    return `${meters}m`
  }
  return `${(meters / 1000).toFixed(2)}km`
}

/**
 * 格式化时间长度
 * @param {number} seconds - 秒数
 * @returns {string}
 */
export function formatDuration(seconds) {
  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const secs = seconds % 60

  if (hours > 0) {
    return `${hours}小时${minutes}分钟`
  }
  if (minutes > 0) {
    return `${minutes}分${secs}秒`
  }
  return `${secs}秒`
}

/**
 * 格式化角度
 * @param {number} angle - 角度值
 * @param {number} decimals - 小数位数
 * @returns {string}
 */
export function formatAngle(angle, decimals = 1) {
  return `${angle.toFixed(decimals)}°`
}

/**
 * 格式化百分比
 * @param {number} value - 值
 * @param {number} total - 总值
 * @param {number} decimals - 小数位数
 * @returns {string}
 */
export function formatPercentage(value, total, decimals = 1) {
  if (total === 0) return '0%'
  const percentage = (value / total) * 100
  return `${percentage.toFixed(decimals)}%`
}

/**
 * 格式化体重
 * @param {number} kg - 公斤
 * @returns {string}
 */
export function formatWeight(kg) {
  return `${kg.toFixed(1)}kg`
}

/**
 * 格式化身高
 * @param {number} cm - 厘米
 * @returns {string}
 */
export function formatHeight(cm) {
  return `${cm.toFixed(0)}cm`
}

/**
 * 格式化温度
 * @param {number} temp - 温度
 * @param {string} unit - 单位
 * @returns {string}
 */
export function formatTemperature(temp, unit = '°C') {
  return `${Math.round(temp)}${unit}`
}

/**
 * 格式化心率
 * @param {number} bpm - 心率
 * @returns {string}
 */
export function formatHeartRate(bpm) {
  return `${Math.round(bpm)} bpm`
}

/**
 * 格式化步数
 * @param {number} steps - 步数
 * @returns {string}
 */
export function formatSteps(steps) {
  if (steps >= 10000) {
    return `${(steps / 10000).toFixed(1)}万步`
  }
  return `${formatNumber(steps)}步`
}

/**
 * 格式化卡路里
 * @param {number} calories - 卡路里
 * @returns {string}
 */
export function formatCalories(calories) {
  return `${Math.round(calories)}千卡`
}

/**
 * 截断字符串
 * @param {string} str - 字符串
 * @param {number} maxLen - 最大长度
 * @param {string} suffix - 后缀
 * @returns {string}
 */
export function truncate(str, maxLen, suffix = '...') {
  if (str.length <= maxLen) return str
  return str.substring(0, maxLen) + suffix
}

/**
 * 生成唯一 ID
 * @returns {string}
 */
export function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2)
}

